const jLoad=(d,id)=>{jd=d;jid=id||null;const e=(id&&JL().find(x=>x.id===id))||{};jdr={ttl:e.ttl||'',txt:e.txt||'',mood:e.mood||0,int:e.int||'',grat:e.grat||'',win:e.win||''};jdirty=false};
