const nrow=n=>{const body=(n.b||'').trim().replace(/\s+/g,' '),hasT=(n.t||'').trim();return`<button class=row onclick="nEd('${n.id}')"><div class=t><span>${n.pin?'📌 ':''}<b>${esc(nTitle(n))}</b></span><span class=s>${esc(pdt(dstr(new Date(n.u))))}</span></div>${hasT&&body?`<div class=s>${esc(body.slice(0,110))}${body.length>110?'…':''}</div>`:''}</button>`};
