function notesV(){return`<div class=acts style="margin-top:16px"><button class="btn sm pri" onclick="nEd()">New note</button></div>${NT().length?`<input id=ns type=search placeholder="Search notes" value="${esc(qn)}" oninput="qn=this.value;$('#nl').innerHTML=nlist()" style="margin-top:14px"><div id=nl style="margin-top:8px">${nlist()}</div>`:empty('No notes yet','Capture ideas, meeting points, anything worth keeping.')}`}
function jrnv(){const S5=[['jr','Journal'],['tk','Tasks'],['hb','Habits'],['cl','Calendar'],['nt','Notes'],['au','Audio']],V={jr:jrV,tk:tkV,hb:hbV,cl:calV,nt:notesV,au:auV};if(!V[jsub])jsub='jr';return head()+`<div class="seg s6">${S5.map(([k,l])=>`<button class="${jsub===k?'on':''}" onclick="jsub='${k}';render()">${l}</button>`).join('')}</div>`+V[jsub]()}
M.addEventListener('click',e=>{if(e.target===M&&ndirty){ndirty=0;render()}});
